/**
 * panels-boot-emitter.test.ts — the ADR-0067 D2 pin: the panels boot block
 * in src/app.html is GENERATED by scripts/sync-theme-applier.mjs, never
 * hand-written. The emitter runs against a temp app.html fixture (DSI_APP_HTML)
 * and the pins are: byte-stable regeneration (idempotent), the profile-suffixed
 * dsi-panels key (namespace.ts:33 mirrored, never imported), publish-only-
 * non-null-string, and the generated-marker comments.
 */
import { describe, expect, it } from 'vitest';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const SCRIPT = join(process.cwd(), 'scripts', 'sync-theme-applier.mjs');

const FIXTURE = [
	'<!doctype html>',
	'<html>',
	'\t<head>',
	'\t\t%sveltekit.head%',
	'\t</head>',
	'</html>'
].join('\n');

function runEmitter(fixtureHtml: string): string {
	const dir = mkdtempSync(join(tmpdir(), 'dsi-panels-emitter-'));
	const htmlPath = join(dir, 'app.html');
	writeFileSync(htmlPath, fixtureHtml);
	execFileSync('node', [SCRIPT], { env: { ...process.env, DSI_APP_HTML: htmlPath } });
	return readFileSync(htmlPath, 'utf8');
}

const beginRe = /<!-- container-base:panels-boot BEGIN[^>]*generated[^>]*-->/;
const endMarker = '<!-- container-base:panels-boot END -->';

describe('panels boot emitter (ADR-0067 D2)', () => {
	it('injects the panels boot block with generated markers into a bare fixture', () => {
		const html = runEmitter(FIXTURE);
		expect(beginRe.test(html)).toBe(true);
		expect(html).toContain(endMarker);
		expect(html).toContain('__BOOT_PREFS');
	});

	it('regenerates byte-stable — a second run produces no diff (idempotent)', () => {
		const once = runEmitter(FIXTURE);
		const dir = mkdtempSync(join(tmpdir(), 'dsi-panels-emitter-'));
		const htmlPath = join(dir, 'app.html');
		writeFileSync(htmlPath, once);
		execFileSync('node', [SCRIPT], { env: { ...process.env, DSI_APP_HTML: htmlPath } });
		expect(readFileSync(htmlPath, 'utf8')).toBe(once);
	});

	it('emitted block reads the profile-suffixed dsi-panels key (mirrors namespace.ts:33)', () => {
		const html = runEmitter(FIXTURE);
		expect(html).toContain("'dsi-panels' + (prof ? '_' + prof : '')");
		expect(html).toContain("__BOOT_PREFS = window.__BOOT_PREFS || {}");
	});

	it('publishes the global ONLY for a non-null, non-empty string', () => {
		const html = runEmitter(FIXTURE);
		expect(html).toContain("if (typeof raw === 'string' && raw.length > 0)");
	});

	it('the emitted block carries NO parse logic — raw string hand-off only (D3)', () => {
		const html = runEmitter(FIXTURE);
		const block = html.slice(html.indexOf(beginRe.exec(html)![0]), html.indexOf(endMarker));
		expect(block).not.toContain('JSON.parse');
		expect(block).not.toContain('clamp');
		expect(block).toContain('localStorage.getItem');
	});
});
